{"draft":{"version":"a0","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pop the Bubbles</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #f4ecd8;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }
  #wrap {
    position: fixed;
    inset: 0;
    display: flex;
    flex-direction: column;
  }
  canvas {
    display: block;
    touch-action: none;
    flex: 1;
  }
  #hud {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 14px;
    box-sizing: border-box;
    pointer-events: none;
  }
  #tally {
    background: #e07a5f;
    color: #f4ecd8;
    font-weight: 800;
    font-size: 18px;
    padding: 8px 16px;
    border-radius: 14px;
    box-shadow: 0 3px 6px rgba(61,64,91,0.3);
  }
  #clearBtn {
    pointer-events: auto;
    background: #3d405b;
    color: #f4ecd8;
    border: none;
    font-weight: 800;
    font-size: 16px;
    padding: 10px 18px;
    min-height: 44px;
    border-radius: 14px;
    box-shadow: 0 3px 6px rgba(61,64,91,0.3);
    cursor: pointer;
  }
  #clearBtn:active {
    transform: translateY(1px);
  }
</style>
</head>
<body>
<div id="wrap">
  <div id="hud">
    <div id="tally">Pops: 0</div>
    <button id="clearBtn">Clear Table</button>
  </div>
  <canvas id="game"></canvas>
</div>
<script>
const CARTRIDGE = {
  send(type, payload = {}) {
    window.parent.postMessage(
      { source: "cartridge", v: 1, type, payload },
      "*",
    );
  },
};
</script>
<script>
(function() {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const tallyEl = document.getElementById("tally");
  const clearBtn = document.getElementById("clearBtn");

  let dpr = window.devicePixelRatio || 1;
  let W = 0, H = 0;

  function resize() {
    W = window.innerWidth;
    H = window.innerHeight;
    dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener("resize", resize);
  resize();

  // seeded jitter helper for paper-cut edges
  function seededRand(seed) {
    let s = seed;
    return function() {
      s = (s * 9301 + 49297) % 233280;
      return s / 233280;
    };
  }

  const PALETTE = {
    background: "#f4ecd8",
    layer: "#e07a5f",
    accent: "#3d405b",
    highlight: "#81b29a"
  };

  const bubbleColors = [PALETTE.layer, PALETTE.highlight, PALETTE.accent];

  let running = false;
  let paused = false;
  let tally = 0;
  const bubbles = [];
  let bubbleId = 0;
  const pops = []; // pop animations

  const MAX_BUBBLES = 9;

  function rand(min, max) {
    return min + Math.random() * (max - min);
  }

  function spawnBubble() {
    const r = rand(28, 48);
    const x = rand(r + 10, Math.max(r + 20, W - r - 10));
    const y = H + r + rand(0, 200);
    const speed = rand(0.4, 1.0);
    const wobbleSeed = Math.floor(rand(1, 99999));
    const color = bubbleColors[Math.floor(rand(0, bubbleColors.length))];
    bubbles.push({
      id: bubbleId++,
      x, y, r,
      speed,
      color,
      wobblePhase: rand(0, Math.PI * 2),
      seed: wobbleSeed
    });
  }

  function ensureBubbles() {
    while (bubbles.length < MAX_BUBBLES) {
      spawnBubble();
    }
  }

  function clearTable() {
    bubbles.length = 0;
    pops.length = 0;
    tally = 0;
    tallyEl.textContent = "Pops: 0";
    CARTRIDGE.send("score", { value: 0 });
    if (running) ensureBubbles();
    draw();
  }

  function backToTitle() {
    running = false;
    bubbles.length = 0;
    pops.length = 0;
    tally = 0;
    tallyEl.textContent = "Pops: 0";
    CARTRIDGE.send("score", { value: 0 });
    draw();
  }

  clearBtn.addEventListener("click", clearTable);

  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  function popBubble(b) {
    bubbles.splice(bubbles.indexOf(b), 1);
    tally += 1;
    tallyEl.textContent = "Pops: " + tally;
    CARTRIDGE.send("score", { value: tally });
    pops.push({ x: b.x, y: b.y, r: b.r, t: 0, color: b.color });
  }

  function hitTest(px, py) {
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      const dx = px - b.x;
      const dy = py - b.y;
      if (dx * dx + dy * dy <= b.r * b.r * 1.15) {
        return b;
      }
    }
    return null;
  }

  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    if (paused) return;
    if (!running) {
      running = true;
      CARTRIDGE.send("start");
      ensureBubbles();
      return;
    }
    const rect = canvas.getBoundingClientRect();
    const px = event.clientX - rect.left;
    const py = event.clientY - rect.top;
    const hit = hitTest(px, py);
    if (hit) {
      popBubble(hit);
    }
  });

  function settle() {
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      b.y -= b.speed;
      b.wobblePhase += 0.02;
      b.x += Math.sin(b.wobblePhase) * 0.3;
      if (b.y < -b.r - 20) {
        bubbles.splice(i, 1);
      }
    }
    if (running) ensureBubbles();
    for (let i = pops.length - 1; i >= 0; i--) {
      pops[i].t += 1;
      if (pops[i].t > 14) pops.splice(i, 1);
    }
  }

  function drawJitterCircle(cx, cy, r, seed, fillStyle) {
    const rnd = seededRand(seed);
    const points = 14;
    ctx.beginPath();
    for (let i = 0; i <= points; i++) {
      const angle = (i / points) * Math.PI * 2;
      const jitter = (rnd() - 0.5) * 2.2;
      const rr = r + jitter;
      const x = cx + Math.cos(angle) * rr;
      const y = cy + Math.sin(angle) * rr;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = fillStyle;
    ctx.fill();
  }

  function drawBackground() {
    ctx.fillStyle = PALETTE.background;
    ctx.fillRect(0, 0, W, H);
    // subtle layered strips at bottom for paper-cut depth
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.25)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    const rnd = seededRand(777);
    ctx.beginPath();
    ctx.moveTo(0, H);
    for (let x = 0; x <= W; x += 40) {
      const jitter = (rnd() - 0.5) * 6;
      ctx.lineTo(x, H - 30 + jitter);
    }
    ctx.lineTo(W, H);
    ctx.closePath();
    ctx.fillStyle = PALETTE.highlight;
    ctx.globalAlpha = 0.5;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function draw() {
    drawBackground();

    if (!running) {
      drawTitleScreen();
      return;
    }

    // bubbles with shadow layer
    for (const b of bubbles) {
      ctx.save();
      ctx.shadowColor = "rgba(61,64,91,0.3)";
      ctx.shadowBlur = 6;
      ctx.shadowOffsetY = 3;
      drawJitterCircle(b.x, b.y, b.r, b.seed, b.color);
      ctx.restore();

      // inner highlight circle (paper layer stacked)
      ctx.save();
      drawJitterCircle(b.x - b.r * 0.25, b.y - b.r * 0.25, b.r * 0.35, b.seed + 5, PALETTE.background);
      ctx.globalAlpha = 0.5;
      ctx.restore();
    }

    // pop animations
    for (const p of pops) {
      const progress = p.t / 14;
      const rr = p.r * (1 + progress * 0.8);
      ctx.save();
      ctx.globalAlpha = Math.max(0, 1 - progress);
      ctx.strokeStyle = PALETTE.accent;
      ctx.lineWidth = 2;
      ctx.beginPath();
      const spikes = 8;
      for (let i = 0; i < spikes; i++) {
        const angle = (i / spikes) * Math.PI * 2;
        const x1 = p.x + Math.cos(angle) * rr * 0.6;
        const y1 = p.y + Math.sin(angle) * rr * 0.6;
        const x2 = p.x + Math.cos(angle) * rr;
        const y2 = p.y + Math.sin(angle) * rr;
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
      }
      ctx.stroke();
      ctx.restore();
    }
  }

  let hintPhase = 0;
  function drawTitleScreen() {
    hintPhase += 0.06;
    const cx = W / 2;
    const cy = H / 2;

    // title plate
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.3)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    const plateW = Math.min(320, W * 0.8);
    const plateH = 90;
    roundRect(cx - plateW / 2, cy - 120, plateW, plateH, 16);
    ctx.fillStyle = PALETTE.layer;
    ctx.fill();
    ctx.restore();

    ctx.fillStyle = PALETTE.background;
    ctx.font = "800 26px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Pop the Bubbles", cx, cy - 75);

    // pulsing hint
    const alpha = 0.6 + 0.4 * Math.sin(hintPhase);
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = PALETTE.accent;
    ctx.font = "700 20px sans-serif";
    ctx.fillText("Tap to begin", cx, cy + 20);
    ctx.restore();

    // decorative bubble samples
    drawJitterCircle(cx - 80, cy + 90, 26, 12, PALETTE.highlight);
    drawJitterCircle(cx, cy + 100, 32, 34, PALETTE.layer);
    drawJitterCircle(cx + 80, cy + 90, 22, 56, PALETTE.accent);
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function frame() {
    if (!paused) settle();
    draw();
    requestAnimationFrame(frame);
  }

  CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
  requestAnimationFrame(() => {
    draw();
    requestAnimationFrame(frame);
  });
})();
</script>
</body>
</html>
"}}

